### Python

```python
import sys
import random


# Treap 的节点
class Node:
    def __init__(self, key, val):
        self.key = key          # 区间左端点
        self.val = val          # 区间右端点
        self.pri = random.randint(1, 1 << 30)  # 随机优先级
        self.left = None
        self.right = None


# 按 key 分裂，返回 (< key, >= key)
def split(root, key):
    if root is None:
        return None, None
    if root.key < key:
        a, b = split(root.right, key)
        root.right = a
        return root, b
    else:
        a, b = split(root.left, key)
        root.left = b
        return a, root


# 合并两棵 Treap，要求左边所有 key 都小于右边
def merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.pri < b.pri:
        a.right = merge(a.right, b)
        return a
    else:
        b.left = merge(a, b.left)
        return b


# 插入一个新区间节点
def insert(root, node):
    if root is None:
        return node
    if node.pri < root.pri:
        a, b = split(root, node.key)
        node.left = a
        node.right = b
        return node
    if node.key < root.key:
        root.left = insert(root.left, node)
    else:
        root.right = insert(root.right, node)
    return root


# 查找 key <= x 的前驱节点
def find_prev(root, x):
    ans = None
    cur = root
    while cur is not None:
        if cur.key <= x:
            ans = cur
            cur = cur.right
        else:
            cur = cur.left
    return ans


# 删除并返回最小节点
def pop_min(root):
    if root.left is None:
        return root.right, root
    new_left, node = pop_min(root.left)
    root.left = new_left
    return root, node


# 删除并返回最大节点
def pop_max(root):
    if root.right is None:
        return root.left, root
    new_right, node = pop_max(root.right)
    root.right = new_right
    return root, node


# 查找最小节点
def get_min(root):
    cur = root
    while cur.left is not None:
        cur = cur.left
    return cur


# 处理题目要求的功能：加入区间并查询
def solve_operations(ops):
    root = None
    ans = []

    for l, r, x in ops:
        # 先按 l 分裂，左边都是左端点 < l 的区间
        a, b = split(root, l)

        # 检查左边最后一个区间是否与 [l, r] 相交
        prev = find_prev(a, 10**30)
        if prev is not None and prev.val >= l:
            a, node = pop_max(a)
            l = min(l, node.key)
            r = max(r, node.val)

        # 把右边所有与 [l, r] 相交的区间不断合并进来
        while b is not None:
            first = get_min(b)
            if first.key > r:
                break
            b, node = pop_min(b)
            r = max(r, node.val)

        # 插入合并后的新区间
        root = merge(a, merge(Node(l, r), b))

        # 查询 x 所在连通块的最右端点
        node = find_prev(root, x)
        if node is not None and node.val >= x:
            ans.append(str(node.val))
        else:
            ans.append(str(x))

    return ans


def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    ops = []
    for _ in range(m):
        l, r, x = map(int, input().split())
        ops.append((l, r, x))

    res = solve_operations(ops)
    sys.stdout.write("\n".join(res))


if __name__ == "__main__":
    main()
```

