#include <iostream>
#include <map>
#include <vector>
#include <array>

using namespace std;


// 处理题目要求的功能：加入区间并查询
vector<int> solveOperations(const vector<array<int, 3>>& ops) {
    // key 为区间左端点，value 为区间右端点
    map<int, int> mp;
    vector<int> ans;
    ans.reserve(ops.size());

    for (auto& op : ops) {
        int l = op[0];
        int r = op[1];
        int x = op[2];

        // 先看左边最后一个区间是否与 [l, r] 相交
        auto it = mp.upper_bound(l);
        if (it != mp.begin()) {
            auto pre = prev(it);
            if (pre->second >= l) {
                l = min(l, pre->first);
                r = max(r, pre->second);
                mp.erase(pre);
            }
        }

        // 不断合并所有与 [l, r] 相交的后续区间
        it = mp.lower_bound(l);
        while (it != mp.end() && it->first <= r) {
            r = max(r, it->second);
            auto toErase = it++;
            mp.erase(toErase);
        }

        // 插入合并后的新区间
        mp[l] = r;

        // 查询 x 所在连通块的最右端点
        it = mp.upper_bound(x);
        if (it != mp.begin()) {
            auto pre = prev(it);
            if (pre->second >= x) {
                ans.push_back(pre->second);
            } else {
                ans.push_back(x);
            }
        } else {
            ans.push_back(x);
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

