    for (int i = 0; i < m; i++) {
        cin >> ops[i][0] >> ops[i][1] >> ops[i][2];
    }

    vector<int> ans = solveOperations(ops);
    for (int v : ans) {
        cout << v << '\n';
    }

    return 0;
}
